	public bool getEventMessage(out EventMessage msg, ushort eventID, int timeout)
	{
		object obj = null;
		while (true)
		{
			msg = (EventMessage)eventMsgQueue.getAsyncMessage(eventID);
			if (msg !=null)
			{
				break;
			}
			if (timeout >= 0)
			{
				if (timeout > 100)
				{
					Thread.Sleep(100);
					timeout -= 100;
				}
				else
				{
					Thread.Sleep(timeout);
					timeout = -1;
				}
				continue;
			}
			msg = (EventMessage)obj;
			return false;
		}
		return true;
	}

