	public bool LogGetMessageFromEventQueue(byte[] logMsg, ulong timeOut)
	{
		object obj = null;
		bool flag = false;
		ushort[] array = new ushort[1];
		byte[] array2 = new byte[2046];
		int num = logMsg.Length;
		if (QLIB_DIAG_GetNextPhoneLog(phoneHandle, array, array2, (uint)timeOut) == 0)
		{
			if (flag)
			{
				if (num < array[0] - 4)
				{
					flag = false;
					array = (ushort[])obj;
					array2 = (byte[])obj;
					return false;
				}
				Array.Copy(array2, 0, logMsg, 0, num);
				array = (ushort[])obj;
			}
			else
			{
				array = (ushort[])obj;
			}
			array2 = (byte[])obj;
			return flag;
		}
		flag = true;
		if (num >= array[0] - 4)
		{
			Array.Copy(array2, 0, logMsg, 0, num);
			array = (ushort[])obj;
			array2 = (byte[])obj;
			return flag;
		}
		flag = false;
		array = (ushort[])obj;
		array2 = (byte[])obj;
		return false;
	}

	public bool DIAG_GetNextPhoneLog(byte[] logMsg, ulong timeOut)
	{
		object obj = null;
		bool flag = false;
		ushort[] array = new ushort[1];
		byte[] array2 = new byte[2046];
		int num = logMsg.Length;
		bool flag2;
		if (QLIB_DIAG_GetNextPhoneLog(phoneHandle, array, array2, (uint)timeOut) == 0)
		{
			flag2 = flag;
		}
		else
		{
			flag = true;
			flag2 = true;
		}
		if (!flag2)
		{
			array = (ushort[])obj;
			array2 = (byte[])obj;
			return flag;
		}
		if (num >= array[0] - 4)
		{
			Array.Copy(array2, 0, logMsg, 0, num);
			array = (ushort[])obj;
			array2 = (byte[])obj;
			return flag;
		}
		flag = false;
		array = (ushort[])obj;
		array2 = (byte[])obj;
		return false;
	}

