			throw new PhoneException(exceptionMessage);
		case 5:
			{
				array = new byte[7];
				b = QLIB_FTM_BT_GET_PERSIST_ACCESS_OPT(phoneHandle, cfgType, array);
				goto IL_00b8;
			}
			IL_00b8:
