			break;
		case WLAN_TX_Mode.EnablingContinuousModulatedTX:
			{
				if ((long)iTxPwr < 5L || (long)iTxPwr > 14L)
				{
					throw new PhoneException(exceptionMessage);
				}
				flag = (long)iAifsn > 252L;
				goto IL_0099;
			}
			IL_0099:
			if (flag)
			{
				throw new PhoneException(exceptionMessage3);
			}
