	private int[] CreateLuhnCheckCode(int[] ImeiValue)
	{
		int num = 0;
		bool flag = true;
		for (int num2 = ImeiValue.Length - 2; num2 >= 0; num2--)
		{
			if (flag)
			{
				int num3 = ImeiValue[num2];
				num3 *= 2;
				if (num3 > 9)
				{
					num3 -= 9;
				}
				num += num3;
			}
			else
			{
				num += ImeiValue[num2];
			}
			flag = !flag;
		}
		int num4 = num % 10;
		if (num4 > 0)
		{
			ImeiValue[ImeiValue.Length - 1] = 10 - num4;
		}
		else
		{
			ImeiValue[ImeiValue.Length - 1] = 0;
		}
		return ImeiValue;
	}

